import React, { useEffect, useState } from 'react';
import './Page1.css'; // Optional: For styling

const Page1 = () => {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    // Fetch data from the backend
    const fetchOrders = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/orders'); // Make sure this path matches your backend API
        const data = await response.json();
        setOrders(data);
      } catch (error) {
        console.error('Error fetching order data:', error);
      }
    };

    fetchOrders();
  }, []);

  // Function to update the status of the order
  const handleConfirm = async (orderId) => {
    try {
      const response = await fetch(`/api/orders/${orderId}/confirm`, { method: 'PATCH' });
  
      if (response.ok) {
        const updatedOrder = await response.json(); // Get the updated order data
        console.log('Updated Order:', updatedOrder); // Log the updated order data
  
        // Update the local state to reflect the change
        setOrders(orders.map(order => 
          order.orderId === orderId ? updatedOrder.order : order
        ));
      } else {
        console.error('Error confirming order:', response.statusText);
      }
    } catch (error) {
      console.error('Error confirming order:', error);
    }
  };

  return (
    <div className="table-container">
      <h2>Orders</h2>
      <table className="order-table">
        <thead>
          <tr>
            <th>Order ID</th>
            <th>Product Name</th>
            <th>Product Price</th>
            <th>Delivery Type</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((order) => (
            <tr key={order._id}>
              <td>{order.orderId}</td>
              <td>{order.productName}</td>
              <td>{order.productPrice}</td>
              <td>{order.deliveryType}</td>
              <td>
                <button onClick={() => handleConfirm(order.orderId)}>Confirm</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Page1;
